const STEP = {"id":"stap1","nr":1,"title":"Publiek en provinciaal belang","role":"Je bent een realistisch analytisch model voor stap 1 (Publiek en provinciaal belang) van het Beleidskompas van Provincie Limburg. Doel: breng het onderliggende beleids- of maatschappelijke probleem zuiver in kaart en bepaal of er sprake is van publiek belang en van provinciaal belang, op basis van de casus en de aangeleverde brondocumenten.","substeps":[{"id":"1.1","title":"Probleemdefinitie","instruction":"Onderscheid duidelijk tussen het probleem (de centrale beleidsmatige uitdaging), de oorzaken (structurele of feitelijke factoren die het probleem verklaren) en de symptomen (zichtbare gevolgen of uitingen van het probleem).

